'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isBoolean = require( '@stdlib/assert/is-boolean' );
var Autosize = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Autosize, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `resize` property', function test( t ) {
	var v;

	v = new Autosize();
	t.strictEqual( hasOwnProp( v, 'resize' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'resize' ), true, 'returns expected value' );
	t.strictEqual( isBoolean( v.resize ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor throws an error if provided an invalid `resize` option', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var autosize = new Autosize({ // eslint-disable-line no-unused-vars
				'resize': value
			});
		};
	}
});

tape( 'the constructor returns an instance having a `resize` property which throws an error if set to a non-boolean value', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var autosize = new Autosize();
			autosize.resize = value;
		};
	}
});

tape( 'the constructor returns an instance having a `resize` property which returns a boolean indicating whether to re-calculate an autosize layout on every view update', function test( t ) {
	var autosize;

	autosize = new Autosize();
	t.strictEqual( autosize.resize, false, 'returns expected value' );

	autosize = new Autosize({
		'resize': true
	});
	t.strictEqual( autosize.resize, true, 'returns expected value' );

	autosize = new Autosize({
		'resize': false
	});
	t.strictEqual( autosize.resize, false, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `resize` property which can be set to a boolean', function test( t ) {
	var autosize;

	autosize = new Autosize();

	autosize.resize = true;
	t.strictEqual( autosize.resize, true, 'returns expected value' );

	autosize.resize = false;
	t.strictEqual( autosize.resize, false, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `resize` property is set to a new value', function test( t ) {
	var autosize;
	var count;

	autosize = new Autosize();
	count = 0;

	autosize.on( 'change', onChange );

	autosize.resize = true;
	t.strictEqual( count, 1, 'returns expected value' );

	autosize.resize = false;
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	autosize.resize = false;
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
